/**
 * PDFBoogie end-to-end suite.
 *
 * Runs the *production build* (dist/, strict CSP) in headless Chromium and
 * exercises every tool with a variety of documents, images, drag & drop,
 * window resizing and list reordering. Outputs are downloaded through the
 * real browser download path and validated in Node (pdfjs / fflate / manual
 * binary checks).
 *
 * Fixtures: e2e/fixtures/*.pdf (generated by e2e/make-fixtures.mjs).
 * Images: generated in-page on <canvas> at exact dimensions.
 */
import { expect, type Page, test } from '@playwright/test';
import {
  captureDownload,
  clickButton,
  docxText,
  docxXml,
  dropFiles,
  dropFixtures,
  firstZipEntry,
  fixtureBytes,
  formFieldValues,
  jpegSize,
  makeCanvasImages,
  odtXml,
  pdfInfo,
  pngSize,
  processAndDownload,
  webpSize,
  zipEntries,
} from './helpers';

/* ------------------------------------------------------------------ */
/* Small conveniences                                                  */
/* ------------------------------------------------------------------ */

const A4 = { w: 595, h: 842 }; // pt (± rounding from the 595.28/841.89 fixtures)

/** Expect no uncaught console errors or pageerrors on the page. */
function expectClean(page: Page) {
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(String(e)));
  return () => {
    expect(errors, `uncaught errors: ${errors.join(' | ')}`).toHaveLength(0);
  };
}

/** Text of each file row (top to bottom). */
const rowNames = (page: Page) => page.locator('ul.filelist .file-row .file-name').allTextContents();

/** Wait until the file list has exactly `n` rows. */
async function expectRows(page: Page, n: number): Promise<void> {
  await expect(async () => {
    expect(await rowNames(page)).toHaveLength(n);
  }).toPass({ timeout: 15_000 });
}

/** Click move-up/down on row `i` (0-based). */
const moveRow = (page: Page, i: number, dir: 'up' | 'down') =>
  page
    .locator('ul.filelist .file-row')
    .nth(i)
    .locator('.file-actions button')
    .nth(dir === 'up' ? 0 : 1)
    .click();

const removeRow = (page: Page, i: number) =>
  page.locator('ul.filelist .file-row').nth(i).locator('.file-actions button').nth(2).click();

/** Assert no horizontal overflow at the current viewport. */
async function noHOverflow(page: Page) {
  const ok = await page.evaluate(
    () => Math.ceil(document.documentElement.scrollWidth) <= window.innerWidth + 1,
  );
  expect(ok, `horizontal overflow at ${await page.evaluate(() => window.innerWidth)}px`).toBe(true);
}

/* ------------------------------------------------------------------ */
/* 1. Site smoke — SSR content + responsive resizing                   */
/* ------------------------------------------------------------------ */

const ROUTES: Array<[string, RegExp]> = [
  ['/', /Free, secure/],
  ['/pdf-compress', /Compress PDF/],
  ['/pdf-merge', /Merge PDF/],
  ['/pdf-combine', /Combine pages/],
  ['/image-to-pdf', /Image to PDF/],
  ['/pdf-to-image', /PDF to [Ii]mage/],
  ['/pdf-to-doc', /PDF to Word/],
  ['/pdf-sign', /Sign/],
  ['/privacy', /Privacy/],
];

test.describe('site smoke', () => {
  for (const [path, h1] of ROUTES) {
    test(`${path} renders SSR h1, no horizontal overflow (1280)`, async ({ page }) => {
      const assertClean = expectClean(page);
      await page.goto(path);
      await expect(page.locator('h1').first()).toContainText(h1);
      await noHOverflow(page);
      // prerendered: content present without JS (meta title matches)
      await expect(page).toHaveTitle(/PDFBoogie|PDF/);
      assertClean();
    });

    test(`${path} holds layout at mobile (360) and tablet (768)`, async ({ page }) => {
      await page.setViewportSize({ width: 360, height: 740 });
      await page.goto(path);
      await expect(page.locator('h1').first()).toContainText(h1);
      await noHOverflow(page);

      await page.setViewportSize({ width: 768, height: 1024 });
      await page.waitForTimeout(150);
      await noHOverflow(page);
    });
  }

  test('unknown path returns 404; the prerendered 404 artifact renders', async ({ page }) => {
    const res = await page.goto('/definitely-not-a-page');
    expect(res?.status()).toBe(404);
    // A static server answers with its own 404; GitHub Pages is configured to serve
    // our prerendered 404.html for unknown paths — verify that artifact renders.
    await page.goto('/404.html');
    await expect(page.locator('h1')).toContainText(/404/);
  });

  test('static assets & SEO files are served', async ({ page }) => {
    for (const p of [
      '/sitemap.xml',
      '/robots.txt',
      '/og.png',
      '/favicon.svg',
      '/manifest.webmanifest',
      '/wasm/pdfcore_bg.wasm',
    ]) {
      const res = await page.request.get(p);
      expect(res.status(), `${p} → ${res.status()}`).toBe(200);
    }
    const sitemap = await page.request.get('/sitemap.xml');
    const body = await sitemap.text();
    expect(body).toContain('/pdf-to-doc');
  });
});

/* ------------------------------------------------------------------ */
/* 2. DropZone — drag & drop behaviour (merge page as reference)       */
/* ------------------------------------------------------------------ */

test.describe('dropzone & drag/drop', () => {
  test('dragenter sets the dragging state; drop clears it', async ({ page }) => {
    await page.goto('/pdf-merge');
    const dz = page.locator('.dropzone');
    expect(await dz.getAttribute('data-dragging')).not.toBe('true');

    await page.evaluate(() => {
      const el = document.querySelector('.dropzone')!;
      const dt = new DataTransfer();
      el.dispatchEvent(
        new DragEvent('dragenter', { bubbles: true, cancelable: true, dataTransfer: dt }),
      );
      el.dispatchEvent(
        new DragEvent('dragover', { bubbles: true, cancelable: true, dataTransfer: dt }),
      );
    });
    await expect(dz).toHaveAttribute('data-dragging', 'true');

    await page.evaluate(() => {
      const el = document.querySelector('.dropzone')!;
      el.dispatchEvent(new DragEvent('dragleave', { bubbles: true, cancelable: true }));
    });
    await expect(dz).toHaveAttribute('data-dragging', 'false');
  });

  test('drop one PDF → one row; drop a second batch appends (order kept)', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-1p.pdf']);
    await expectRows(page, 1);
    expect(await rowNames(page)).toEqual(['text-1p.pdf']);

    await dropFixtures(page, ['text-5p.pdf', 'landscape-1p.pdf']);
    await expectRows(page, 3);
    expect(await rowNames(page)).toEqual(['text-1p.pdf', 'text-5p.pdf', 'landscape-1p.pdf']);
    assertClean();
  });

  test('dropping a non-PDF is rejected with a friendly error', async ({ page }) => {
    await page.goto('/pdf-merge');
    await dropFiles(page, [{ name: 'notes.txt', type: 'text/plain', data: [110, 105] }]);
    await expect(page.locator('.error-card')).toContainText('Not PDF or images: notes.txt');
    await expectRows(page, 0);
  });

  test('native <input type=file> path registers files', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await page
      .locator('.dz-input')
      .first()
      .setInputFiles([
        {
          name: 'text-1p.pdf',
          mimeType: 'application/pdf',
          buffer: Buffer.from(fixtureBytes('text-1p.pdf')),
        },
        {
          name: 'text-5p.pdf',
          mimeType: 'application/pdf',
          buffer: Buffer.from(fixtureBytes('text-5p.pdf')),
        },
      ]);
    await expectRows(page, 2);
    expect(await rowNames(page)).toEqual(['text-1p.pdf', 'text-5p.pdf']);
    assertClean();
  });

  test('dropzone tap target covers the zone (mobile-safe)', async ({ page }) => {
    await page.setViewportSize({ width: 375, height: 700 });
    await page.goto('/pdf-merge');
    const hit = await page.evaluate(() => {
      const dz = document.querySelector('.dropzone') as HTMLElement;
      const r = dz.getBoundingClientRect();
      const el = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
      const input = document.querySelector('.dropzone input[type=file]') as HTMLElement | null;
      return el === input || (el !== null && input?.contains(el as Node));
    });
    expect(hit).toBe(true);
  });
});

/* ------------------------------------------------------------------ */
/* 3. Ordering — merge list reorder / remove + merge respects order    */
/* ------------------------------------------------------------------ */

test.describe('ordering (merge)', () => {
  test('up/down/remove controls reorder and prune the list', async ({ page }) => {
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-1p.pdf', 'text-5p.pdf', 'landscape-1p.pdf']);
    await expectRows(page, 3);

    // move first down → [5p, 1p, landscape]
    await moveRow(page, 0, 'down');
    expect(await rowNames(page)).toEqual(['text-5p.pdf', 'text-1p.pdf', 'landscape-1p.pdf']);
    // move last up → [5p, landscape, 1p]
    await moveRow(page, 2, 'up');
    expect(await rowNames(page)).toEqual(['text-5p.pdf', 'landscape-1p.pdf', 'text-1p.pdf']);
    // remove middle → [5p, 1p]
    await removeRow(page, 1);
    await expectRows(page, 2);
    expect(await rowNames(page)).toEqual(['text-5p.pdf', 'text-1p.pdf']);
  });

  test('merged PDF page order matches the final list order (text markers)', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    // [1p, 5p, landscape] → move 1p to the end → [5p, landscape, 1p]
    await dropFixtures(page, ['text-1p.pdf', 'text-5p.pdf', 'landscape-1p.pdf']);
    await expectRows(page, 3);
    await moveRow(page, 0, 'down'); // 1p → index 1: [5p, 1p, landscape]
    await moveRow(page, 1, 'down'); // 1p → index 2: [5p, landscape, 1p]
    expect(await rowNames(page)).toEqual(['text-5p.pdf', 'landscape-1p.pdf', 'text-1p.pdf']);

    const pdf = await processAndDownload(page, /^Merge 7 pages into one PDF$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(7); // 5 + 1 + 1
    const texts = info.pages.map((p) => p.text);
    // pages 1-5 from text-5p, page 6 landscape, page 7 text-1p
    expect(texts[0]!).toContain('MARK-P1');
    expect(texts[4]!).toContain('MARK-P5');
    expect(texts[5]!).toContain('MARK-LANDSCAPE');
    expect(texts[6]!).toContain('MARK-ONE');
    assertClean();
  });

  test('mixing images + PDF: images get the chosen page size, PDFs keep theirs', async ({
    page,
  }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await makeCanvasImages(page, [
      { name: 'img-a.jpg', mime: 'image/jpeg', w: 600, h: 400, paint: 'hgrad' },
      { name: 'img-b.png', mime: 'image/png', w: 400, h: 600, paint: 'vgrad' },
    ]);
    await dropFixtures(page, ['text-1p.pdf']);
    await expectRows(page, 3);
    await page.selectOption('#mergePageSize', 'a4');

    const pdf = await processAndDownload(page, /^Merge 3 pages into one PDF$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(3);
    const near = (a: number, b: number, tol = 2) => Math.abs(a - b) <= tol;
    // both image pages are A4 portrait; the PDF page keeps A4 too (fixture is A4)
    for (const pg of info.pages) {
      expect(near(pg.w, A4.w) && near(pg.h, A4.h), `page ${pg.w}×${pg.h}`).toBe(true);
    }
    assertClean();
  });

  test('encrypted PDF in merge → flagged on the row, merge disabled, no download', async ({
    page,
  }) => {
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-1p.pdf', 'encrypted.pdf']);
    await expectRows(page, 2);
    await expect(page.locator('.file-warn').first()).toContainText(/password|protected/i);
    await expect(page.locator('button.btn-primary')).toBeDisabled();
    await expect(page.locator('.result-card')).toHaveCount(0);
  });

  test('page strip renders every page as a thumbnail; CTA counts pages', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-5p.pdf', 'text-1p.pdf']);
    await expect(page.locator('.seq-tile')).toHaveCount(6);
    const thumbs = page.locator('.seq-tile img.seq-thumb');
    await expect(thumbs).toHaveCount(6);
    const w = await thumbs.first().evaluate((el) => el.naturalWidth);
    expect(w, 'thumbnails actually rendered').toBeGreaterThan(0);
    await expect(page.getByRole('button', { name: 'Merge 6 pages into one PDF' })).toBeEnabled();
    assertClean();
  });

  test('page-level reorder (arrows) changes the merged page order', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-5p.pdf', 'text-1p.pdf']);
    await expect(page.locator('.seq-tile')).toHaveCount(6);

    // move page 3 of text-5p to the front (two slots left)
    const left = page.getByRole('button', { name: 'Move page 3 of text-5p.pdf left' });
    await left.click();
    await left.click();

    const pdf = await processAndDownload(page, /^Merge 6 pages into one PDF$/);
    const texts = (await pdfInfo(pdf)).pages.map((p) => p.text);
    expect(texts.map((t) => /MARK-(P\d|ONE)/.exec(t)![1])).toEqual([
      'P3',
      'P1',
      'P2',
      'P4',
      'P5',
      'ONE',
    ]);
    assertClean();
  });

  test('pointer drag (grip) reorders the strip', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    // [1p, 5p×5] → drag the first tile's grip onto the last tile
    await dropFixtures(page, ['text-1p.pdf', 'text-5p.pdf']);
    const tiles = page.locator('.seq-tile');
    await expect(tiles).toHaveCount(6);
    const grip = tiles.first().locator('.seq-grip');
    const last = tiles.last();
    const g = (await grip.boundingBox())!;
    const t = (await last.boundingBox())!;
    await page.mouse.move(g.x + g.width / 2, g.y + g.height / 2);
    await page.mouse.down();
    await page.mouse.move(t.x + t.width / 2, t.y + t.height / 2, { steps: 12 });
    await page.mouse.up();

    // 1p now sits before the last tile
    const ids = await tiles.evaluateAll((els) => els.map((e) => e.dataset.seqId!));
    expect(ids[4]!.endsWith('::1')).toBe(true);

    const pdf = await processAndDownload(page, /^Merge 6 pages into one PDF$/);
    const texts = (await pdfInfo(pdf)).pages.map((p) => p.text);
    expect(texts[4]!).toContain('MARK-ONE');
    expect(texts[5]!).toContain('MARK-P5');
    assertClean();
  });

  test('tap multi-select: the selection drags as a block', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-1p.pdf', 'text-5p.pdf']);
    const tiles = page.locator('.seq-tile');
    await expect(tiles).toHaveCount(6);

    // tap tile bodies to select 1p + 5p/p1
    await tiles.nth(0).click();
    await tiles.nth(1).click();
    await expect(page.locator('.seq-tile.is-selected')).toHaveCount(2);
    await expect(page.locator('.seq-clear')).toContainText('2 selected');

    // drag the second selected tile's grip onto the last tile →
    // both selected pages land before it (in sequence order)
    const grip = tiles.nth(1).locator('.seq-grip');
    const last = tiles.last();
    const g = (await grip.boundingBox())!;
    const t = (await last.boundingBox())!;
    await page.mouse.move(g.x + g.width / 2, g.y + g.height / 2);
    await page.mouse.down();
    await page.mouse.move(t.x + t.width / 2, t.y + t.height / 2, { steps: 12 });
    await page.mouse.up();

    const pdf = await processAndDownload(page, /^Merge 6 pages into one PDF$/);
    const texts = (await pdfInfo(pdf)).pages.map((p) => p.text);
    expect(texts[3]!).toContain('MARK-ONE');
    expect(texts[4]!).toContain('MARK-P1');
    expect(texts[5]!).toContain('MARK-P5');
    assertClean();
  });

  test('selection arrows nudge the selected block one slot', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-merge');
    await dropFixtures(page, ['text-5p.pdf', 'text-1p.pdf']);
    const tiles = page.locator('.seq-tile');
    await expect(tiles).toHaveCount(6);

    // select P1 + P2 (tiles 0, 1), nudge right → P3 slips in before them
    await tiles.nth(0).click();
    await tiles.nth(1).click();
    await page.getByRole('button', { name: 'Move page 1 of text-5p.pdf right' }).click();

    const pdf = await processAndDownload(page, /^Merge 6 pages into one PDF$/);
    const texts = (await pdfInfo(pdf)).pages.map((p) => p.text);
    expect(texts[0]!).toContain('MARK-P3');
    expect(texts[1]!).toContain('MARK-P1');
    expect(texts[2]!).toContain('MARK-P2');
    expect(texts[3]!).toContain('MARK-P4');
    assertClean();
  });
});

/* ------------------------------------------------------------------ */
/* 4. Combine (n-up)                                                    */
/* ------------------------------------------------------------------ */

test.describe('combine pages (n-up)', () => {
  test('page tiles render; selecting 2,4,5 at 2-up → 2 sheets', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-combine');
    await dropFixtures(page, ['text-5p.pdf']);
    await expect(page.locator('.page-tile')).toHaveCount(5);
    // default = all selected
    expect(await page.locator('.page-tile[aria-pressed="true"]').count()).toBe(5);

    // unselect all, then pick 2, 4, 5
    await clickButton(page, /^None$/);
    expect(await page.locator('.page-tile[aria-pressed="true"]').count()).toBe(0);
    await page.locator('.page-tile', { hasText: /^2$/ }).click();
    await page.locator('.page-tile', { hasText: /^4$/ }).click();
    await page.locator('.page-tile', { hasText: /^5$/ }).click();
    expect(await page.locator('.page-tile[aria-pressed="true"]').count()).toBe(3);

    await page.selectOption('#grid', '2');
    const pdf = await processAndDownload(page, /^Combine 3 pages$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(2); // ceil(3/2)
    expect(Math.round(info.pages[0]!.w)).toBeCloseTo(A4.w, -1);
    assertClean();
  });

  test('all 5 pages: 4-up → 2 sheets; 16-up → 1 sheet', async ({ page }) => {
    await page.goto('/pdf-combine');
    await dropFixtures(page, ['text-5p.pdf']);
    await page.selectOption('#grid', '4');
    const pdf = await processAndDownload(page, /^Combine 5 pages$/);
    expect((await pdfInfo(pdf)).pages).toHaveLength(2); // ceil(5/4)

    // restart with the same file, switch grid, recombine
    await clickButton(page, /Adjust and combine again/);
    await page.selectOption('#grid', '16');
    const pdf2 = await processAndDownload(page, /^Combine 5 pages$/);
    expect((await pdfInfo(pdf2)).pages).toHaveLength(1); // ceil(5/16)
  });

  test('9-up landscape sheet: output page is landscape A4', async ({ page }) => {
    await page.goto('/pdf-combine');
    await dropFixtures(page, ['text-5p.pdf']);
    await page.selectOption('#grid', '9');
    await page.selectOption('#sheetSize', 'a4');
    await page.selectOption('#orientation', 'landscape');
    const pdf = await processAndDownload(page, /^Combine 5 pages$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(1);
    expect(info.pages[0]!.w).toBeGreaterThan(info.pages[0]!.h);
    expect(Math.round((info.pages[0]!.w / 842) * 10)).toBe(10); // ~842pt wide
  });

  test('page tiles show rendered thumbnails of the real pages', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-combine');
    await dropFixtures(page, ['text-5p.pdf']);
    await expect(page.locator('.page-tile')).toHaveCount(5);
    await expect(page.locator('.page-tile img.page-tile-img')).toHaveCount(5);
    const w = await page
      .locator('.page-tile img.page-tile-img')
      .first()
      .evaluate((el) => el.naturalWidth);
    expect(w, 'thumbnails actually rendered').toBeGreaterThan(0);
    assertClean();
  });

  test('None selected → combine button disabled', async ({ page }) => {
    await page.goto('/pdf-combine');
    await dropFixtures(page, ['text-5p.pdf']);
    await clickButton(page, /^None$/);
    await expect(page.locator('button', { hasText: /Combine selected/ })).toBeDisabled();
  });
});

/* ------------------------------------------------------------------ */
/* 5. Image → PDF                                                      */
/* ------------------------------------------------------------------ */

test.describe('image to PDF', () => {
  test('4 canvas images → 4 pages; fit pages match image aspect (pt = px×0.75)', async ({
    page,
  }) => {
    const assertClean = expectClean(page);
    await page.goto('/image-to-pdf');
    await makeCanvasImages(page, [
      { name: 'a.png', mime: 'image/png', w: 800, h: 600, paint: 'solid', color: [200, 60, 60] },
      { name: 'b.png', mime: 'image/png', w: 600, h: 800, paint: 'solid', color: [60, 120, 200] },
      { name: 'c.png', mime: 'image/png', w: 1000, h: 400, paint: 'quarters' },
      { name: 'd.png', mime: 'image/png', w: 256, h: 256, paint: 'solid', color: [60, 180, 90] },
    ]);
    await expectRows(page, 4);

    const pdf = await processAndDownload(page, /^Combine 4 images into a PDF$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(4);
    const near = (a: number, b: number, tol = 2) => Math.abs(a - b) <= tol;
    expect(near(info.pages[0]!.w, 600) && near(info.pages[0]!.h, 450)).toBe(true); // 800×600 px
    expect(near(info.pages[1]!.w, 450) && near(info.pages[1]!.h, 600)).toBe(true); // 600×800 px
    expect(near(info.pages[2]!.w, 750) && near(info.pages[2]!.h, 300)).toBe(true); // 1000×400 px
    expect(near(info.pages[3]!.w, 192) && near(info.pages[3]!.h, 192)).toBe(true); // 256×256 px
    assertClean();
  });

  test('reordering changes output page order', async ({ page }) => {
    await page.goto('/image-to-pdf');
    await makeCanvasImages(page, [
      { name: 'a.png', mime: 'image/png', w: 800, h: 400, paint: 'solid', color: [200, 60, 60] },
      { name: 'b.png', mime: 'image/png', w: 400, h: 800, paint: 'solid', color: [60, 120, 200] },
      { name: 'c.png', mime: 'image/png', w: 500, h: 500, paint: 'solid', color: [90, 90, 200] },
    ]);
    await expectRows(page, 3);
    // move last to front: [a,b,c] → [a,c,b] → [c,a,b]
    await moveRow(page, 2, 'up'); // c → index 1
    await moveRow(page, 1, 'up'); // c → index 0
    expect(await rowNames(page)).toEqual(['c.png', 'a.png', 'b.png']);

    const pdf = await processAndDownload(page, /^Combine 3 images into a PDF$/);
    const info = await pdfInfo(pdf);
    const near = (a: number, b: number, tol = 2) => Math.abs(a - b) <= tol;
    // first page now the 500×500 image → 375×375 pt
    expect(near(info.pages[0]!.w, 375) && near(info.pages[0]!.h, 375)).toBe(true);
    // second page the 800×400 image → 600×300 pt
    expect(near(info.pages[1]!.w, 600) && near(info.pages[1]!.h, 300)).toBe(true);
  });

  test('A4 page size normalizes every page', async ({ page }) => {
    await page.goto('/image-to-pdf');
    await makeCanvasImages(page, [
      { name: 'a.png', mime: 'image/png', w: 900, h: 300, paint: 'solid' },
      { name: 'b.png', mime: 'image/png', w: 300, h: 900, paint: 'solid', color: [0, 150, 150] },
    ]);
    await expectRows(page, 2);
    await page.selectOption('#pageSize', 'a4');
    const pdf = await processAndDownload(page, /^Combine 2 images into a PDF$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(2);
    for (const pg of info.pages) {
      expect(Math.abs(pg.w - A4.w)).toBeLessThanOrEqual(2);
      expect(Math.abs(pg.h - A4.h)).toBeLessThanOrEqual(2);
    }
  });

  test('JPEG and WebP inputs both produce a valid multi-page PDF', async ({ page }) => {
    await page.goto('/image-to-pdf');
    await makeCanvasImages(page, [
      { name: 'a.jpg', mime: 'image/jpeg', w: 700, h: 500, paint: 'quarters' },
      { name: 'b.webp', mime: 'image/webp', w: 500, h: 700, paint: 'hgrad' },
    ]);
    await expectRows(page, 2);
    const pdf = await processAndDownload(page, /^Combine 2 images into a PDF$/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(2);
  });

  test('removing an image before convert drops its page', async ({ page }) => {
    await page.goto('/image-to-pdf');
    await makeCanvasImages(page, [
      { name: 'a.png', mime: 'image/png', w: 400, h: 300, paint: 'solid' },
      { name: 'b.png', mime: 'image/png', w: 300, h: 400, paint: 'solid', color: [200, 100, 0] },
    ]);
    await expectRows(page, 2);
    await removeRow(page, 0);
    await expectRows(page, 1);
    expect(await rowNames(page)).toEqual(['b.png']);
    const pdf = await processAndDownload(page, /^Combine 1 image into a PDF$/);
    expect((await pdfInfo(pdf)).pages).toHaveLength(1);
  });
});

