test.describe('compress', () => {
  test('lossless: valid PDF, page count preserved (text-5p)', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['text-5p.pdf']);
    const pdf = await processAndDownload(page, /Compress \(lossless\)/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(5);
    assertClean();
  });

  test('lossless on image-heavy: 3 valid pages', async ({ page }) => {
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['image-heavy-3p.pdf']);
    const pdf = await processAndDownload(page, /Compress \(lossless\)/);
    expect((await pdfInfo(pdf)).pages).toHaveLength(3);
  });

  test('strong 96 DPI on image-heavy → smaller than input, 3 pages', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['image-heavy-3p.pdf']);
    const inputSize = await page.evaluate(async () =>
      (await fetch('/e2e/fixtures/image-heavy-3p.pdf')).arrayBuffer().then((b) => b.byteLength),
    );
    // enable strong mode
    await page.locator('label.toggle input[type=checkbox]').check();
    await page.selectOption('#cdpi', '96');
    const pdf = await processAndDownload(page, /Compress \(strong\)/);
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(3);
    expect(pdf.byteLength, 'strong output should shrink a raster-heavy PDF').toBeLessThan(
      inputSize,
    );
    assertClean();
  });

  test('encrypted PDF → friendly error, no crash', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['encrypted.pdf']);
    await clickButton(page, /Compress \(lossless\)/);
    await expect(page.locator('.error-card')).toBeVisible();
    assertClean();
  });

  test('auto-picks strong for an image-heavy PDF, with a reason note', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['image-heavy-3p.pdf']);
    const note = page.locator('.auto-note');
    await expect(note).toBeVisible();
    await expect(note).toContainText(/image-heavy/);
    await expect(page.locator('label.toggle input[type=checkbox]')).toBeChecked();
    assertClean();
  });

  test('auto-picks lossless for a text PDF; manual switch clears the note', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['text-5p.pdf']);
    const note = page.locator('.auto-note');
    await expect(note).toBeVisible();
    await expect(note).toContainText(/text\/?vector/);
    const box = page.locator('label.toggle input[type=checkbox]');
    await expect(box).not.toBeChecked();
    await box.check();
    await expect(note).toHaveCount(0);
    await expect(box).toBeChecked();
    assertClean();
  });

  test('page preview strip renders thumbnails of the first pages', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['text-5p.pdf']);
    await expect(page.locator('.thumb-strip img')).toHaveCount(5);
    const w = await page
      .locator('.thumb-strip img')
      .first()
      .evaluate((el) => el.naturalWidth);
    expect(w, 'thumbnails actually rendered').toBeGreaterThan(0);
    assertClean();
  });

  test('quality slider + value do not overlap at 360px', async ({ page }) => {
    await page.setViewportSize({ width: 360, height: 740 });
    await page.goto('/pdf-compress');
    await dropFixtures(page, ['text-1p.pdf']);
    await page.locator('label.toggle input[type=checkbox]').check(); // show the slider row
    const row = page.locator('.range-row').first();
    const slider = row.locator('input[type=range]');
    const out = row.locator('output');
    const sBox = (await slider.boundingBox())!;
    const oBox = (await out.boundingBox())!;
    expect(oBox.x + oBox.width, 'value within viewport').toBeLessThanOrEqual(361);
    expect(oBox.x, 'value does not overlap the slider').toBeGreaterThanOrEqual(
      sBox.x + sBox.width - 2,
    );
  });
});

