test.describe('sign & fill', () => {
  test('form panel lists all four fields', async ({ page }) => {
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['form.pdf']);
    // the form scan is async — wait for the last field to appear
    await expect(page.locator('.field > span[title="country"]')).toBeVisible();
    const names = await page
      .locator('.field > span[title]')
      .evaluateAll((els) => els.map((e) => e.getAttribute('title')));
    expect(names).toEqual(expect.arrayContaining(['name', 'email', 'agree', 'country']));
  });

  test('fill text + checkbox + dropdown → apply → values persist in the PDF', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['form.pdf']);
    await expect(page.locator('.field:has(span[title="name"]) input')).toBeVisible();
    await page.locator('.field:has(span[title="name"]) input').fill('Ada Lovelace');
    await page.locator('.field:has(span[title="email"]) input').fill('ada@example.com');
    // custom toggle: the visible control is the knob (the input is visually
    // hidden but real, layered over the knob) — clicking the input is what
    // the toggle does for the user
    await page.locator('.field:has(span[title="agree"]) .toggle input[type="checkbox"]').click();
    await expect(
      page.locator('.field:has(span[title="agree"]) input[type=checkbox]'),
    ).toBeChecked();
    await page.locator('.field:has(span[title="country"]) select').selectOption('DE');
    await clickButton(page, /Apply form fill/);

    // form-only download is now allowed
    const pdf = await captureDownload(page, () => clickButton(page, /Download filled PDF/));
    const values = await formFieldValues(pdf);
    expect(values.name).toBe('Ada Lovelace');
    expect(values.email).toBe('ada@example.com');
    expect(values.agree).toBe(true);
    expect(String(values.country)).toBe('DE');
    assertClean();
  });

  test('drawn signature: draw → use → place on page → download a bigger valid PDF', async ({
    page,
  }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['text-1p.pdf']);
    // draw a zigzag on the signature pad
    const pad = page.locator('canvas.sig-pad');
    const box = (await pad.boundingBox())!;
    await page.mouse.move(box.x + 15, box.y + box.height / 2);
    await page.mouse.down();
    for (let i = 1; i <= 14; i += 1) {
      await page.mouse.move(box.x + 15 + i * 12, box.y + box.height / 2 + (i % 2 === 0 ? -14 : 14));
    }
    await page.mouse.up();
    await clickButton(page, /^Use this signature$/);
    await expect(page.locator('.sig-preview img')).toHaveCount(1);
    // placing mode starts automatically on "Use this signature"
    const stage = page.locator('.stage[data-page="1"]');
    const sbox = (await stage.boundingBox())!;
    await page.mouse.click(sbox.x + sbox.width / 2, sbox.y + sbox.height * 0.75);
    await expect(page.locator('.stamp')).toHaveCount(1);

    const inputSize = await page.evaluate(async () =>
      (await fetch('/e2e/fixtures/text-1p.pdf')).arrayBuffer().then((b) => b.byteLength),
    );
    const pdf = await captureDownload(page, () =>
      clickButton(page, /Download signed PDF \(1 stamp\)/),
    );
    const info = await pdfInfo(pdf);
    expect(info.pages).toHaveLength(1);
    expect(pdf.byteLength).toBeGreaterThan(inputSize); // an image stamp was embedded
    assertClean();
  });

  test('typed signature → download a valid PDF', async ({ page }) => {
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['text-1p.pdf']);
    await page.locator('[role=tab]', { hasText: 'Type' }).click();
    await page.getByPlaceholder(/Alex Rivera/).fill('Alex Rivera');
    await clickButton(page, /^Use this signature$/);
    await expect(page.locator('.sig-preview img')).toHaveCount(1);
    // placing mode starts automatically on "Use this signature"
    const stage = page.locator('.stage[data-page="1"]');
    const sbox = (await stage.boundingBox())!;
    await page.mouse.click(sbox.x + 80, sbox.y + sbox.height * 0.8);
    await expect(page.locator('.stamp')).toHaveCount(1);
    const pdf = await captureDownload(page, () =>
      clickButton(page, /Download signed PDF \(1 stamp\)/),
    );
    expect((await pdfInfo(pdf)).pages).toHaveLength(1);
  });

  test('signature upload tab: drop a PNG → preview appears', async ({ page }) => {
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['text-1p.pdf']);
    await page.locator('[role=tab]', { hasText: 'Upload' }).click();
    // a second dropzone is now the upload one — target it specifically
    await page.evaluate(async () => {
      const c = document.createElement('canvas');
      c.width = 300;
      c.height = 100;
      const ctx = c.getContext('2d')!;
      ctx.strokeStyle = '#111';
      ctx.lineWidth = 6;
      ctx.beginPath();
      ctx.moveTo(10, 50);
      ctx.bezierCurveTo(80, 10, 150, 90, 290, 40);
      ctx.stroke();
      const blob = await new Promise<Blob | null>((r) => c.toBlob(r, 'image/png'));
      const dt = new DataTransfer();
      dt.items.add(new File([blob!], 'sig.png', { type: 'image/png' }));
      // the upload dropzone is the one inside the signature panel (last on page)
      const zones = document.querySelectorAll('.dropzone');
      const target = zones[zones.length - 1] as HTMLElement;
      target.dispatchEvent(
        new DragEvent('drop', { bubbles: true, cancelable: true, dataTransfer: dt }),
      );
    });
    await expect(page.locator('.sig-preview img')).toHaveCount(1);
  });

  test('encrypted PDF → friendly error', async ({ page }) => {
    const assertClean = expectClean(page);
    await page.goto('/pdf-sign');
    await dropFixtures(page, ['encrypted.pdf']);
    await expect(page.locator('.error-card')).toBeVisible();
    assertClean();
  });
});

